package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.raids.*;import io.xeros.content.minigames.inferno.*;import io.xeros.content.minigames.pest_control.*;import io.xeros.content.minigames.rfd.DisposeTypes;import io.xeros.content.combat.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.cycleevent.*;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class SoloActivitiesPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(String name){Player p=BossRoutesCheck.actor();p.setLoginName(name);p.setDisplayName(name);p.getCollectionLog().setSaveName(name);p.combatLevel=126;p.getHealth().setMaximumHealth(1000000);p.getHealth().reset();return p;}static void apply(Player p){BossesPlayableCheck.applied(p);p.teleTimer=0;}static void tick(Player p,int n){for(int i=0;i<n;i++){SkillsAuditCheck.tick(1);apply(p);}}static void clear(Player p){ToaSoloPlayableCheck.clear(p);}static void kill(Player p,NPC n){n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);ok(n.isDead(),"NPC death "+n.getNpcId());for(int i=0;i<40&&!n.needRespawn&&!n.isUnregister();i++)Server.npcHandler.getNpcProcess().process(n.getIndex());}
 static Player reload(String name)throws Exception{Player q=actor(name);ok(PlayerSave.loadGame(q,name,"IsolatedAudit",true).toString().equals("SUCCESS"),"Real save load "+name);return q;}
 static void cox()throws Exception{Player p=actor("cox66qa");ok(SoloCox.enter(p),"Cox solo entry");apply(p);SoloCox a=(SoloCox)p.getInstance();Field f=SoloCox.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(a,(IntUnaryOperator)(b->0));int rooms=0,npcs=0;Set<Integer> seen=new HashSet<>();for(int steps=0;p.getInstance()!=null&&steps<30;steps++){List<NPC> mobs=new ArrayList<>(a.getNpcs());boolean fought=false;for(NPC n:mobs){if(n.isDead()||n.isUnregister())continue;if(n.getNpcId()==7554&&(!p.getRaidsInstance().rightHand||!p.getRaidsInstance().leftHand))continue;ok(n.getInstance()==a&&n.heightLevel==p.heightLevel,"Cox wrong private floor");seen.add(n.getNpcId());kill(p,n);npcs++;fought=true;}if(fought)rooms++;tick(p,8);}ok(p.getInstance()==null&&p.raidCount==1&&rooms>=8&&seen.containsAll(List.of(7553,7554,7555,7544,7566,7585,7563)),"Cox full native progression "+rooms+" "+seen);ok(p.coxSoloStage==0,"Cox checkpoint reset");ok(PlayerSave.saveGameInstant(p),"Cox save");Player q=reload("cox66qa");ok(q.raidCount==1&&q.coxSoloStage==0&&q.getTeleportToX()==1245,"Cox reload reward/exit");clear(p);clear(q);System.out.println("COX_NATIVE_EIGHT_COMBAT_ROOMS_OLM_HANDS_HEAD_PRIVATE_FLOORS_REWARD_REAL_SAVE_RELOAD_PASS NPCS="+npcs);
 p=actor("coxresume66qa");SoloCox.enter(p);apply(p);a=(SoloCox)p.getInstance();for(NPC n:new ArrayList<>(a.getNpcs()))kill(p,n);tick(p,8);ok(p.coxSoloStage==2,"Cox second-room checkpoint");PlayerSave.saveGameInstant(p);clear(p);q=reload("coxresume66qa");q.teleTimer=0;ok(q.coxSoloStage==2&&q.getTeleportToX()==1245,"Cox checkpoint load");apply(q);SoloCox.enter(q);apply(q);ok(q.getInstance().getNpcs().stream().anyMatch(n->n.getNpcId()==7604),"Cox resumed wrong room");q.getInstance().handleDeath(q);ok(q.coxSoloStage==0&&q.getInstance()==null,"Cox death reset");clear(q);System.out.println("COX_CHECKPOINT_REENTRY_AND_SAFE_DEATH_PASS");}
 static void inferno()throws Exception{Player p=actor("inferno66qa");ok(Inferno.getDefaultWave()==0,"Inferno default first wave");Inferno.startInferno(p,0);apply(p);Inferno a=p.getInferno();ok(a!=null,"Inferno entry");a.end(DisposeTypes.COMPLETE);ok(p.getInstance()==a&&p.getItems().getInventoryCount(21295)==0,"Premature cape");Set<Integer> ids=new HashSet<>();int kills=0;for(int wave=0;wave<68;wave++){ok(a.getInfernoWaveId()==wave,"Inferno wrong wave "+wave+" actual "+a.getInfernoWaveId()+" remaining "+a.getKillsRemaining());tick(p,23);for(int sweep=0;sweep<8&&a.getInfernoWaveId()==wave;sweep++){List<NPC> ns=new ArrayList<>(a.getNpcs());for(NPC n:ns)if(!n.isDead()&&!n.isUnregister()&&NPCHandler.isInfernoNpc(n)&&n.getNpcId()!=7707&&n.getNpcId()!=7706){ids.add(n.getNpcId());kill(p,n);a.onNpcDeath(n);kills++;}tick(p,1);}ok(a.getInfernoWaveId()==wave+1,"Inferno stalled "+wave+" remaining "+a.getKillsRemaining());}tick(p,35);NPC zuk=a.getNpcs().stream().filter(n->n.getNpcId()==7706&&!n.isDead()).findFirst().orElseThrow();ok(a.getNpcs().stream().anyMatch(n->n.getNpcId()==7707),"Zuk glyph missing");while(p.getItems().freeSlots()>0)p.getItems().addItem(526,1);kill(p,zuk);a.end(DisposeTypes.COMPLETE);tick(p,3);ok(p.getInstance()==null&&p.infernoSoloCompletions==1&&p.infernoSoloWave==0&&p.getItems().bankContains(21295),"Inferno cape once/full bag instance="+p.getInstance()+" completions="+p.infernoSoloCompletions+" wave="+p.infernoSoloWave+" bank="+p.getItems().bankContains(21295)+" inv="+p.getItems().getInventoryCount(21295)+" dead="+zuk.isDead()+" hp="+zuk.getHealth().getCurrentHealth());ok(PlayerSave.saveGameInstant(p),"Inferno save");Player q=reload("inferno66qa");ok(q.infernoSoloCompletions==1&&q.infernoSoloWave==0&&q.getItems().bankContains(21295)&&q.getTeleportToX()==2497,"Inferno save reload");clear(p);clear(q);System.out.println("INFERNO_ALL_69_WAVES_BLOB_SPLITS_SINGLE_TRIPLE_JAD_ZUK_GLYPH_ONE_CAPE_FULL_BAG_BANK_REAL_SAVE_RELOAD_PASS KILLS="+kills+" IDS="+ids);
 p=actor("infernoresume66qa");p.infernoSoloWave=35;Inferno.startInferno(p,0);apply(p);a=p.getInferno();ok(a.getInfernoWaveId()==35,"Inferno resume");PlayerSave.saveGameInstant(p);a.leaveGame();tick(p,40);ok(p.getInstance()==null,"Inferno leave");q=reload("infernoresume66qa");ok(q.infernoSoloWave==35&&q.getTeleportToX()==2497,"Inferno checkpoint reload");apply(q);Inferno.startInferno(q,0);apply(q);q.getInferno().handleDeath(q);ok(q.infernoSoloWave==0&&q.getInstance()==null,"Inferno death");clear(p);clear(q);System.out.println("INFERNO_CHECKPOINT_RESUME_LEAVE_CANCEL_SAFE_DEATH_PASS");}
 static void pest()throws Exception{Player p=actor("pest66qa");int initial=p.pcPoints;ok(SoloPest.enter(p),"Pest solo entry");apply(p);SoloPest a=(SoloPest)p.getInstance();System.out.println("PEST KNIGHT "+a.getNpcs().stream().filter(n->n.getNpcId()==1756).findFirst().get().getName());tick(p,1);ok(a.getNpcs().size()==9,"Pest knight portals enemies");for(NPC n:new ArrayList<>(a.getNpcs()))if(n.getNpcId()>=1739&&n.getNpcId()<=1742)kill(p,n);ok(p.getInstance()==null&&p.pcPoints==initial+5,"Pest win points");ok(PlayerSave.saveGameInstant(p),"Pest save");Player q=reload("pest66qa");ok(q.pcPoints==initial+5&&q.getTeleportToX()==2657,"Pest point reload");clear(p);clear(q);
 p=actor("pestloss66qa");SoloPest.enter(p);apply(p);a=(SoloPest)p.getInstance();NPC knight=a.getNpcs().stream().filter(n->n.getNpcId()==1756).findFirst().get();knight.getHealth().setMaximumHealth(1000000);knight.getHealth().reset();tick(p,1000);ok(p.getInstance()==null&&p.pcPoints==0,"Pest timer loss/reward");clear(p);
 p=actor("pestshop66qa");p.pcPoints=200;while(p.getItems().freeSlots()>0)p.getItems().addItem(526,1);p.getPestControlRewards().click(144210);p.getPestControlRewards().click(144138);ok(p.pcPoints==200&&!p.getItems().playerHasItem(8839),"Pest full bag charge");p.getItems().deleteItem2(526,1);p.getPestControlRewards().click(144138);ok(p.pcPoints==25&&p.getItems().playerHasItem(8839),"Pest Void shop");ok(PlayerSave.saveGameInstant(p),"Pest shop save");q=reload("pestshop66qa");ok(q.pcPoints==25&&q.getItems().playerHasItem(8839),"Pest shop reload");clear(p);clear(q);System.out.println("PEST_PRIVATE_SOLO_FOUR_PORTALS_ENEMIES_KNIGHT_WIN_TIMEOUT_VOID_ATOMIC_FULL_BAG_AND_REAL_SAVE_RELOAD_PASS");}
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;if(args.length==0||args[0].equals("cox"))cox();if(args.length==0||args[0].equals("inferno"))inferno();if(args.length==0||args[0].equals("pest"))pest();System.out.println("SOLO_ACTIVITIES_V66_PASS");System.exit(0);}
}
